; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; LOOP: main loop and the surface commands (1BD5-207D).
;
; The turn on the surface and in towns, and the surface commands. The key loop itself is at the
; end of EXDATA (ReadCommand: BuildView; ReadCommandNoView: prompt, wait for a key or a timeout = Space, look it
; up in SurfaceKeys, SI = the prompt from SurfacePrompts, jump through SurfaceCmds). Every
; command ends with jmp MainLoop, which is the end of a turn rather than the key loop:
;   MainLoop   fights and dungeons go to their own loops; otherwise count the moves, leave a
;              town at its edge, poison, the moons and moon gates, whirlpools, the fire of
;              Exodus's castle, then the creatures' turn (MonTurn, WORLD) and back to ReadCommandNoView.
; The handlers are entered with SI = the prompt and
; print it first: CmdPass Pass, CmdNorth/CmdSouth/CmdEast/CmdWest North/South/East/West, CmdBoard Board,
; CmdCast Cast, CmdEnter Enter, CmdHand Hand, CmdLook Look, CmdModify Modify order, CmdPeer Peer at gem,
; CmdQuit Quit & Save, CmdSteal Steal, CmdUnlock Unlock, CmdVolume Volume, CmdXit X-it, CmdZtats Ztats.
; Several are in the dungeon table too (DungeonCmds: Pass, Cast, Hand, Modify, Peer, Volume,
; Ztats).
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN Random:NEAR
EXTRN LoadFile:NEAR
EXTRN DrawView:NEAR
EXTRN ViewTileAt:NEAR
EXTRN SoundOn:BYTE
EXTRN Sound:NEAR
EXTRN Ofs80h:BYTE
EXTRN MapBuf:BYTE
EXTRN DungeonMap:BYTE
EXTRN MonTile:BYTE
EXTRN Moon1Phase:BYTE
EXTRN PartyTile:BYTE
EXTRN Location:BYTE
EXTRN PartySize:BYTE
EXTRN PartyXY:BYTE
EXTRN PlayerXY:BYTE
EXTRN PlayerY:BYTE
EXTRN DungeonLevel:BYTE
EXTRN TimeStop:BYTE
EXTRN FileDungeonDat:BYTE
EXTRN MapFileNames:BYTE
EXTRN MapPosTbl:BYTE
EXTRN MsgArrow:BYTE
EXTRN MsgMountHorse:BYTE
EXTRN MsgBoardFrigate:BYTE
EXTRN MsgWhoseKey:BYTE
EXTRN MsgCraft:BYTE
EXTRN MsgOn:BYTE
EXTRN MsgOff:BYTE
EXTRN MsgDungeon:BYTE
EXTRN MsgTowne:BYTE
EXTRN MsgCastle:BYTE
EXTRN MsgPlayer:BYTE
EXTRN MsgExchanged:BYTE
EXTRN MsgToPlayer:BYTE
EXTRN MsgDirect:BYTE
EXTRN MsgStealFailed:BYTE
EXTRN MsgWatchOut:BYTE
EXTRN MsgOnlyOnSurface:BYTE
EXTRN MsgPleaseWait:BYTE
EXTRN SaveSosaria:NEAR
EXTRN AdvanceMoons:NEAR
EXTRN Whirlpool:NEAR
EXTRN MonTurn:NEAR
EXTRN MapWraps:BYTE
EXTRN TileEast:BYTE
EXTRN TileWest:BYTE
EXTRN TileNorth:BYTE
EXTRN TileSouth:BYTE
EXTRN TileHere:BYTE
EXTRN ShowGemMap:NEAR
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN DrawFrame:NEAR
EXTRN BuildView:NEAR
EXTRN MapCellAddr:NEAR
EXTRN ShowDungeonMap:NEAR
EXTRN Facing:BYTE
EXTRN InExodusCastle:NEAR
EXTRN MoonGateJump:NEAR
EXTRN DexRoll:NEAR
EXTRN CastSpell:NEAR
EXTRN EnterShrine:NEAR
EXTRN ExitToSosaria:NEAR
EXTRN CardsInserted:BYTE
EXTRN PrintName:NEAR
EXTRN IsUp:NEAR
EXTRN AskPlayer:NEAR
EXTRN StatusLine:NEAR
EXTRN DrawPlayerNums:NEAR
EXTRN ShowZtats:NEAR
EXTRN PartyUpkeep:NEAR
EXTRN AgainstWind:NEAR
EXTRN CheckTerrain:NEAR
EXTRN AskDirection:NEAR
EXTRN HandEquip:NEAR
EXTRN MsgNoneLeft:NEAR
EXTRN MsgWhat:NEAR
EXTRN MsgInvalidMove:NEAR
EXTRN MsgNotHere:NEAR
EXTRN MsgIncapacitated:NEAR
EXTRN AddMoves:NEAR
EXTRN ChestLoot:NEAR
EXTRN DamageParty:NEAR
EXTRN EnterDungeon:NEAR
EXTRN DungeonTurnEnd:NEAR
EXTRN HitTile:BYTE
EXTRN PlayerTurnEnd:NEAR
EXTRN PrintMoves:NEAR
PUBLIC MainLoop
PUBLIC CmdPass
PUBLIC CmdNorth
PUBLIC CmdSouth
PUBLIC CmdEast
PUBLIC CmdWest
PUBLIC CmdBoard
PUBLIC CmdCast
PUBLIC CmdEnter
PUBLIC CmdHand
PUBLIC CmdLook
PUBLIC CmdModify
PUBLIC CmdPeer
PUBLIC CmdQuit
PUBLIC CmdSteal
PUBLIC CmdUnlock
PUBLIC CmdVolume
PUBLIC CmdXit
PUBLIC CmdZtats
;------------------------------------------------------------------------------
; MainLoop: the end of every turn (all commands jump here). Location 80h (a fight) -> PlayerTurnEnd,
; 1 (dungeon) -> DungeonTurnEnd. Otherwise: add PartySize to MoveCount; in a town, castle (Location 2,
; 3) or Ambrosia (0FFh) a party at x 0 or y 0 leaves for Sosaria (ExitToSosaria); poison (PartyUpkeep);
; the moons step (AdvanceMoons), and a party on a moon gate before or after the step is teleported
; (MoonGateJump); a whirlpool under the frigate takes it (Whirlpool); inside Exodus's castle (InExodusCastle)
; fire strikes a random cell of the view and Negate Time is cancelled. Then jmp MonTurn (the
; creatures, BuildView, the key loop).
;------------------------------------------------------------------------------
MainLoop:	cmp byte ptr Location, 80h	; 80h: a fight	;@1BD5
	jne MainLoop_NotCombat	;@1BDA
	jmp PlayerTurnEnd	;@1BDC
MainLoop_NotCombat:	cmp byte ptr Location, 1	; dungeon	;@1BDF
	jne MainLoop_Surface	;@1BE4
	jmp DungeonTurnEnd	;@1BE6
MainLoop_Surface:	mov al, byte ptr PartySize	;@1BE9
	call AddMoves	; MoveCount += PartySize	;@1BEC
	cmp byte ptr Location, 2	; towns and castles (2, 3), also Ambrosia (0FFh)	;@1BEF
	jb MainLoop_Poison	;@1BF4
	cmp byte ptr PlayerXY, 0	; at the map's edge (x 0 or y 0; PlayerY = y)	;@1BF6
	je MainLoop_LeaveTown	;@1BFB
	cmp byte ptr PlayerY, 0	;@1BFD
	jne MainLoop_Poison	;@1C02
MainLoop_LeaveTown:	call ExitToSosaria	; "Exit to Sosaria"	;@1C04
MainLoop_Poison:	call PartyUpkeep	; poison	;@1C07
	mov bx, word ptr PlayerXY	;@1C0A
	call MapCellAddr	;@1C0E
	cmp al, 88h	; on a moon gate (shape 34)	;@1C11
	jne MainLoop_Moons	;@1C13
	call MoonGateJump	; the gate teleport	;@1C15
	call AdvanceMoons	;@1C18
	jmp short MainLoop_Whirl	;@1C1B
MainLoop_Moons:	call AdvanceMoons	;@1C1D
	mov bx, word ptr PlayerXY	;@1C20
	call MapCellAddr	;@1C24
	cmp al, 88h	;@1C27
	jne MainLoop_Whirl	;@1C29
	call MoonGateJump	;@1C2B
MainLoop_Whirl:	cmp al, 30h	; whirlpool (shape 12)	;@1C2E
	jne MainLoop_Fire	;@1C30
	call Whirlpool	;@1C32
MainLoop_Fire:	call InExodusCastle	; ZF set inside Exodus's castle (?)	;@1C35
	jne MainLoop_Monsters	;@1C38
	mov byte ptr TimeStop, 0	; Negate Time does not work there	;@1C3A
	mov dh, 0Bh	; a random view cell: BL = column, BH = row (0-10)	;@1C3F
	call Random	;@1C41
	mov bl, dl	;@1C44
	call Random	;@1C46
	mov bh, dl	;@1C49
	cmp bx, 505h	; the party's own cell? (ViewTileAt keeps the flags)	;@1C4B
	call ViewTileAt	;@1C4F
	jne MainLoop_FireFloor	;@1C52
	call BuildView	;@1C54
	mov byte ptr [bx], 3Dh	; Fire on the party	;@1C57
	call DrawView	;@1C5A
	call DamageParty	; DamageParty: damage every player (DUNMOVE DamageParty)	;@1C5D
	jmp short MainLoop_Monsters	;@1C60
MainLoop_FireFloor:	cmp al, 8	; floor	;@1C62
	jne MainLoop_Monsters	;@1C64
	call DrawView	;@1C66
	mov byte ptr [bx], 3Dh	; Fire there, harmless	;@1C69
	call DrawView	;@1C6C
	mov al, 0F7h	; sound 0F7h	;@1C6F
	call Sound	;@1C71
MainLoop_Monsters:	jmp MonTurn	; the creatures' turn (WORLD)	;@1C74
;------------------------------------------------------------------------------
; CmdPass: Space, also when no key comes in time: print "Pass".
;------------------------------------------------------------------------------
CmdPass:	call PrintMsg	;@1C77
	jmp MainLoop	;@1C7A
;------------------------------------------------------------------------------
; CmdNorth, CmdSouth, CmdEast, CmdWest: the arrow keys.
; AgainstWind refuses a frigate in a calm or against the wind (?), CheckTerrain the tile on that side
; (TileNorth-TileEast, filled by BuildView) if the party cannot enter it; else move one cell (the
; coordinates wrap at 64). Refused: "Invalid move" (MsgInvalidMove).
;------------------------------------------------------------------------------
CmdNorth:	call PrintMsg	;@1C7D
	mov al, 1	; direction 1 = north	;@1C80
	call AgainstWind	;@1C82
	jne CmdNorth_Blocked	;@1C85
	mov al, byte ptr TileNorth	; TileNorth = the tile north (TileNorth)	;@1C87
	call CheckTerrain	;@1C8A
	jne CmdNorth_Blocked	;@1C8D
	dec byte ptr PlayerY	; y - 1	;@1C8F
	and byte ptr PlayerY, 3Fh	;@1C93
	jmp MainLoop	;@1C98
CmdNorth_Blocked:	jmp MsgInvalidMove	;@1C9B
CmdSouth:	call PrintMsg	;@1C9E
	mov al, 3	; 3 = south	;@1CA1
	call AgainstWind	;@1CA3
	jne CmdSouth_Blocked	;@1CA6
	mov al, byte ptr TileSouth	; TileSouth = TileSouth	;@1CA8
	call CheckTerrain	;@1CAB
	jne CmdSouth_Blocked	;@1CAE
	inc byte ptr PlayerY	;@1CB0
	and byte ptr PlayerY, 3Fh	;@1CB4
	jmp MainLoop	;@1CB9
CmdSouth_Blocked:	jmp MsgInvalidMove	;@1CBC
CmdEast:	call PrintMsg	;@1CBF
	mov al, 2	; 2 = east	;@1CC2
	call AgainstWind	;@1CC4
	jne CmdEast_Blocked	;@1CC7
	mov al, byte ptr TileEast	; TileEast = TileEast	;@1CC9
	call CheckTerrain	;@1CCC
	jne CmdEast_Blocked	;@1CCF
	inc byte ptr PlayerXY	;@1CD1
	and byte ptr PlayerXY, 3Fh	;@1CD5
	jmp MainLoop	;@1CDA
CmdEast_Blocked:	jmp MsgInvalidMove	;@1CDD
CmdWest:	call PrintMsg	;@1CE0
	mov al, 4	; 4 = west	;@1CE3
	call AgainstWind	;@1CE5
	jne CmdWest_Blocked	;@1CE8
	mov al, byte ptr TileWest	; TileWest = TileWest	;@1CEA
	call CheckTerrain	;@1CED
	jne CmdWest_Blocked	;@1CF0
	dec byte ptr PlayerXY	;@1CF2
	and byte ptr PlayerXY, 3Fh	;@1CF6
	jmp MainLoop	;@1CFB
CmdWest_Blocked:	jmp MsgInvalidMove	;@1CFE
;------------------------------------------------------------------------------
; CmdBoard: on foot, on a horse (map byte 28h) or a frigate (2Ch): the craft
; leaves the map (grass or water stays) and becomes PartyTile; "Mount Horse!" / "Board
; Frigate!". Otherwise "What?". There is no horse to mount in Ambrosia (and trying cancels
; Negate Time).
;------------------------------------------------------------------------------
CmdBoard:	cmp byte ptr PartyTile, 3Fh	; on foot?	;@1D01
	jne CmdBoard_What	;@1D06
	mov bx, word ptr PlayerXY	;@1D08
	call MapCellAddr	;@1D0C
	cmp al, 28h	; horse (shape 10)	;@1D0F
	je CmdBoard_Horse	;@1D11
	cmp al, 2Ch	; frigate (shape 11)	;@1D13
	je CmdBoard_Frigate	;@1D15
CmdBoard_What:	call PrintMsg	;@1D17
	jmp MsgWhat	;@1D1A
CmdBoard_Horse:	cmp byte ptr Location, 0FFh	;@1D1D
	jne CmdBoard_Mount	;@1D22
	mov byte ptr TimeStop, 0	; an odd side effect: Negate Time ends	;@1D24
	jmp CmdBoard_What	;@1D29
CmdBoard_Mount:	mov byte ptr [bx], 4	; grass under the horse	;@1D2B
	mov byte ptr PartyTile, 0Ah	; on a horse	;@1D2E
	lea si, MsgMountHorse	; "Mount Horse!"	;@1D33
	call PrintMsg	;@1D37
	jmp short CmdBoard_Done	;@1D3A
CmdBoard_Frigate:	mov byte ptr [bx], 0	; water under the frigate	;@1D3C
	mov byte ptr PartyTile, 0Bh	; in a frigate	;@1D3F
	lea si, MsgBoardFrigate	; "Board Frigate!"	;@1D44
	call PrintMsg	;@1D48
CmdBoard_Done:	jmp MainLoop	;@1D4B
;------------------------------------------------------------------------------
; CmdCast: ask the player; if Good or Poisoned cast a spell (CastSpell, MAGIC);
; else "Incapacitated".
;------------------------------------------------------------------------------
CmdCast:	call PrintMsg	;@1D4E
	call AskPlayer	;@1D51
	je CmdCast_Done	;@1D54
	call IsUp	;@1D56
	jne CmdCast_Down	;@1D59
	mov byte ptr HitTile, 3Ch	; 3Ch outside a fight (COMBAT sets 3Dh) ?	;@1D5B
	call CastSpell	;@1D60
CmdCast_Done:	jmp MainLoop	;@1D63
CmdCast_Down:	jmp MsgIncapacitated	;@1D66
;------------------------------------------------------------------------------
; CmdEnter: in Ambrosia, enter a shrine (map byte 0F8h, shape 62: EnterShrine,
; SHRINE). On Sosaria: the party's place must be one of the 19 entrances of MapPosTbl (its index
; picks the file in MapFileNames); the tile there decides: dungeon (5) -> level 0 at (1)
; facing 1, Location 1; Towne (6) -> (1, 32), Location 2; castle (7) -> (32, 62), Location 3,
; and the castle's card counter (CardsInserted) cleared; towns and castles do not wrap (MapWraps = 0).
; Then "Please wait...", Sosaria is saved (SaveSosaria) and the file loaded (the moon phases kept);
; a dungeon loads its level file at DungeonMap and DUNGEON.DAT at MapBuf and goes to EnterDungeon.
;------------------------------------------------------------------------------
CmdEnter:	call PrintMsg	;@1D69
	cmp byte ptr Location, 0	;@1D6C
	je CmdEnter_Sosaria	;@1D71
	cmp byte ptr Location, 0FFh	;@1D73
	jne CmdEnter_What	;@1D78
	mov bx, word ptr PlayerXY	;@1D7A
	call MapCellAddr	;@1D7E
	cmp al, 0F8h	; shrine (shape 62)	;@1D81
	jne CmdEnter_What	;@1D83
	call EnterShrine	;@1D85
	jmp CmdEnter_Done	;@1D88
CmdEnter_What:	jmp MsgWhat	;@1D8B
CmdEnter_Sosaria:	mov ax, word ptr PlayerXY	;@1D8E
	cld	;@1D91
	mov cx, 13h	; 19 entrances (x, y words)	;@1D92
	mov bx, cx	;@1D95
	lea di, MapPosTbl	;@1D97
	repne scasw	;@1D9B
	jne CmdEnter_What	;@1D9D
	sub bx, cx	; BX = the entrance's index * 2	;@1D9F
	dec bx	;@1DA1
	shl bx, 1	;@1DA2
	mov ax, word ptr PlayerXY	; the place to come back to	;@1DA4
	mov word ptr PartyXY, ax	;@1DA7
	cmp byte ptr TileHere, 5	; TileHere = TileHere: dungeon (shape 5)	;@1DAA
	jne CmdEnter_TryTowne	;@1DAF
	lea si, MsgDungeon	; "Dungeon!"	;@1DB1
	call PrintMsg	;@1DB5
	mov dl, 1	; the new Location	;@1DB8
	mov byte ptr DungeonLevel, 0	;@1DBA
	mov word ptr PlayerXY, 101h	;@1DBF
	mov byte ptr Facing, 1	;@1DC5
	jmp short CmdEnter_Load	;@1DCA
CmdEnter_TryTowne:	cmp byte ptr TileHere, 6	; Towne (shape 6)	;@1DCC
	jne CmdEnter_TryCastle	;@1DD1
	lea si, MsgTowne	; "Towne!"	;@1DD3
	call PrintMsg	;@1DD7
	mov dl, 2	;@1DDA
	mov word ptr PlayerXY, 2001h	; x 1, y 32: the west edge	;@1DDC
	mov byte ptr MapWraps, 0	; MapWraps = MapWraps: no	;@1DE2
	jmp short CmdEnter_Load	;@1DE7
CmdEnter_TryCastle:	cmp byte ptr TileHere, 7	; castle (shape 7)	;@1DE9
	jne CmdEnter_What	;@1DEE
	lea si, MsgCastle	; "Castle!"	;@1DF0
	call PrintMsg	;@1DF4
	mov dl, 3	;@1DF7
	mov word ptr PlayerXY, 3E20h	; x 32, y 62: the south edge	;@1DF9
	mov byte ptr MapWraps, 0	;@1DFF
	mov word ptr CardsInserted, 0	; the cards inserted (ACTIONS 7670)	;@1E04
CmdEnter_Load:	lea si, MsgPleaseWait	; "Please wait..."	;@1E0A
	call PrintMsg	;@1E0E
	call SaveSosaria	; save Sosaria and the party	;@1E11
	mov byte ptr Location, dl	;@1E14
	mov si, bx	;@1E18
	mov dx, word ptr MapFileNames[si]	; DX = the map's file name	;@1E1A
	cmp byte ptr Location, 1	;@1E1E
	je CmdEnter_Dungeon	;@1E23
	push word ptr Moon1Phase	; the phases are part of the map file: keep them	;@1E25
	lea bx, MapBuf	;@1E29
	mov cx, 1228h	;@1E2D
	call LoadFile	;@1E30
	pop word ptr Moon1Phase	;@1E33
CmdEnter_Done:	jmp MainLoop	;@1E37
CmdEnter_Dungeon:	mov cx, 890h	; the dungeon: eight levels and messages	;@1E3A
	lea bx, DungeonMap	;@1E3D
	call LoadFile	;@1E41
	lea bx, MapBuf	;@1E44
	mov cx, 800h	;@1E48
	lea dx, FileDungeonDat	;@1E4B
	call LoadFile	;@1E4F
	jmp EnterDungeon	; the dungeon loop	;@1E52
;------------------------------------------------------------------------------
; CmdHand: Hand equipment: from a player to another (not the same: "What?");
; HandEquip (HAND) asks what and how much.
;------------------------------------------------------------------------------
CmdHand:	call PrintMsg	;@1E55
	call AskPlayer	;@1E58
	je CmdHand_Done	;@1E5B
	lea si, MsgToPlayer	; "  To Player: "	;@1E5D
	call PrintMsg	;@1E61
	mov si, bx	; SI = the giver	;@1E64
	call AskPlayer	;@1E66
	je CmdHand_Done	;@1E69
	mov di, bx	;@1E6B
	cmp si, di	;@1E6D
	je CmdHand_Same	;@1E6F
	call HandEquip	;@1E71
CmdHand_Done:	jmp MainLoop	;@1E74
CmdHand_Same:	jmp MsgWhat	;@1E77
;------------------------------------------------------------------------------
; CmdLook: ask a direction (AskDirection: BX = the cell, Esc gives
; ZF); print "->" and the name of the shape there.
;------------------------------------------------------------------------------
CmdLook:	call PrintMsg	;@1E7A
	call AskDirection	;@1E7D
	je CmdLook_Done	;@1E80
	lea si, MsgArrow	; "->"	;@1E82
	call PrintMsg	;@1E86
	call MapCellAddr	;@1E89
	shr al, 1	; the shape number	;@1E8C
	shr al, 1	;@1E8E
	inc al	; PrintName prints name AL-1	;@1E90
	call PrintName	;@1E92
	call ScrollMsg	;@1E95
CmdLook_Done:	jmp MainLoop	;@1E98
;------------------------------------------------------------------------------
; CmdModify: Modify order: exchange two players: their bytes at PARTY.ULT
; header 0A-0D (14C4 + slot, probably their roster numbers) and their 64-byte records; then
; redraw the screen (frame, player numbers, moons unless in a dungeon, status) and print
; "Exchanged!".
;------------------------------------------------------------------------------
CmdModify:	call PrintMsg	;@1E9B
	call AskPlayer	;@1E9E
	je CmdModify_Done	;@1EA1
	mov dl, al	; DL = the first slot (0-3), DI = its record	;@1EA3
	dec dl	;@1EA5
	mov di, bx	;@1EA7
	lea si, MsgPlayer	; "Player: "	;@1EA9
	call PrintMsg	;@1EAD
	call AskPlayer	;@1EB0
	je CmdModify_Done	;@1EB3
	mov dh, al	; DH = the second slot, SI = its record	;@1EB5
	dec dh	;@1EB7
	mov si, bx	;@1EB9
	mov cx, si	;@1EBB
	lea si, PartyTile	;@1EBD
	mov bl, dl	;@1EC1
	mov bh, 0	;@1EC3
	mov al, byte ptr [bx+si+0Ah]	; header byte 0A + slot (14C4)	;@1EC5
	mov bl, dh	;@1EC8
	xchg byte ptr [bx+si+0Ah], al	;@1ECA
	mov bl, dl	;@1ECD
	mov byte ptr [bx+si+0Ah], al	;@1ECF
	mov si, cx	;@1ED2
	cld	;@1ED4
	mov cx, 40h	; exchange the 64-byte records	;@1ED5
CmdModify_Swap:	mov al, byte ptr [di]	;@1ED8
	xchg byte ptr [si], al	;@1EDA
	stosb	;@1EDC
	inc si	;@1EDD
	loop CmdModify_Swap	;@1EDE
	call DrawFrame	; DrawFrame	;@1EE0
	call DrawPlayerNums	; the player numbers	;@1EE3
	cmp byte ptr Location, 1	; no moons in a dungeon	;@1EE6
	je CmdModify_Status	;@1EEB
	call AdvanceMoons	;@1EED
CmdModify_Status:	call StatusLine	;@1EF0
	lea si, MsgExchanged	; "Exchanged!"	;@1EF3
	call PrintMsg	;@1EF7
CmdModify_Done:	jmp MainLoop	;@1EFA
;------------------------------------------------------------------------------
; CmdPeer: Peer at a gem: a player spends a gem (BCD) and sees the map:
; ShowGemMap on the surface and in towns, ShowDungeonMap in a dungeon.
; No gem: "None left" (MsgNoneLeft).
;------------------------------------------------------------------------------
CmdPeer:	call PrintMsg	;@1EFD
	call AskPlayer	;@1F00
	je CmdPeer_Done	;@1F03
	mov al, byte ptr [bx+25h]	; gems	;@1F05
	sub al, 1	;@1F08
	das	; BCD; carry: none	;@1F0A
	jb CmdPeer_None	;@1F0B
	mov byte ptr [bx+25h], al	;@1F0D
	cmp byte ptr Location, 1	;@1F10
	je CmdPeer_Dungeon	;@1F15
	call ShowGemMap	;@1F17
	jmp short CmdPeer_Done	;@1F1A
CmdPeer_Dungeon:	call ShowDungeonMap	;@1F1C
CmdPeer_Done:	jmp MainLoop	;@1F1F
CmdPeer_None:	jmp MsgNoneLeft	;@1F22
;------------------------------------------------------------------------------
; CmdQuit: Quit & Save, on Sosaria only: keep the position in PARTY.ULT,
; print the move count (PrintMoves), "Please wait...", save SOSARIA.ULT and PARTY.ULT, and go on
; playing (the program does not end). Elsewhere: "Only on surface!" and sound 0FFh.
;------------------------------------------------------------------------------
CmdQuit:	call PrintMsg	;@1F25
	cmp byte ptr Location, 0	;@1F28
	jne CmdQuit_NotSurface	;@1F2D
	mov ax, word ptr PlayerXY	;@1F2F
	mov word ptr PartyXY, ax	;@1F32
	call PrintMoves	; the moves so far	;@1F35
	lea si, MsgPleaseWait	; "Please wait..."	;@1F38
	call PrintMsg	;@1F3C
	call SaveSosaria	; save Sosaria and the party	;@1F3F
CmdQuit_Done:	jmp MainLoop	;@1F42
CmdQuit_NotSurface:	lea si, MsgOnlyOnSurface	; "Only on surface!"	;@1F45
	call PrintMsg	;@1F49
	mov al, 0FFh	;@1F4C
	call Sound	;@1F4E
	jmp CmdQuit_Done	;@1F51
;------------------------------------------------------------------------------
; CmdSteal: a player (Good or Poisoned) steals in a direction. If the roll
; succeeds (DexRoll: dexterity and class) and the cell there is a shop counter (shapes 37-57)
; with a chest (24h) right behind it, the chest becomes floor and the gold is taken (ChestLoot).
; Otherwise, one time in four "Watch out!" and every guard in town turns hostile (MonTalk
; 0C0h), else "Failed!".
;------------------------------------------------------------------------------
CmdSteal:	call PrintMsg	;@1F53
	call AskPlayer	;@1F56
	je CmdSteal_Done	;@1F59
	mov di, bx	; DI = the thief	;@1F5B
	call IsUp	;@1F5D
	jne CmdSteal_Down	;@1F60
	lea si, MsgDirect	; "Direct? "	;@1F62
	call PrintMsg	;@1F66
	call AskDirection	;@1F69
	je CmdSteal_Done	;@1F6C
	mov cx, bx	; CX = the cell, DX = the step (AskDirection)	;@1F6E
	mov bx, di	;@1F70
	call DexRoll	; ZF set: the roll succeeded	;@1F72
	je CmdSteal_Counter	;@1F75
CmdSteal_Fail:	mov dh, 0FFh	;@1F77
	call Random	;@1F79
	and dl, 3	; one time in four: the guards	;@1F7C
	je CmdSteal_Alarm	;@1F7F
	lea si, MsgStealFailed	; "Failed!"	;@1F81
	call PrintMsg	;@1F85
	jmp short CmdSteal_Done	;@1F88
CmdSteal_Alarm:	lea bx, MonTile	;@1F8A
	mov cx, 20h	;@1F8E
CmdSteal_Guards:	cmp byte ptr [bx], 48h	; guard (shape 18)	;@1F91
	jne CmdSteal_NextMon	;@1F94
	mov byte ptr Ofs80h[bx], 0C0h	; 0080h + MonTile + n = MonTalk + n: hostile	;@1F96
CmdSteal_NextMon:	inc bx	;@1F9B
	loop CmdSteal_Guards	;@1F9C
	lea si, MsgWatchOut	; "Watch out!"	;@1F9E
	call PrintMsg	;@1FA2
	mov al, 0FAh	; sound 0FAh	;@1FA5
	call Sound	;@1FA7
	jmp short CmdSteal_Done	;@1FAA
CmdSteal_Counter:	mov bx, cx	;@1FAC
	call MapCellAddr	;@1FAE
	cmp al, 94h	; counter: shapes 37 (wall) - 57 (letters)	;@1FB1
	jb CmdSteal_Fail	;@1FB3
	cmp al, 0E4h	;@1FB5
	ja CmdSteal_Fail	;@1FB7
	add cl, dl	; two steps on: behind the counter	;@1FB9
	add cl, dl	;@1FBB
	add ch, dh	;@1FBD
	add ch, dh	;@1FBF
	mov bx, cx	;@1FC1
	call MapCellAddr	;@1FC3
	cmp al, 24h	; chest (shape 9)	;@1FC6
	jne CmdSteal_Fail	;@1FC8
	mov byte ptr [bx], 20h	; floor	;@1FCA
	call ChestLoot	; the gold in the chest	;@1FCD
CmdSteal_Done:	jmp MainLoop	;@1FD0
CmdSteal_Down:	jmp MsgIncapacitated	;@1FD3
;------------------------------------------------------------------------------
; CmdUnlock: unlock a door east or west of the party (a door north or south
; cannot be unlocked: the direction must have DH = 0): map byte 0B8h (shape 46); a player
; gives a key (BCD) and the door becomes the tile the party stands on. Else "Not here!" or
; "None left".
;------------------------------------------------------------------------------
CmdUnlock:	call PrintMsg	;@1FD6
	call AskDirection	;@1FD9
	je CmdUnlock_Done	;@1FDC
	test dh, 0FFh	; east or west only	;@1FDE
	jne CmdUnlock_NotHere	;@1FE1
	call MapCellAddr	;@1FE3
	cmp al, 0B8h	; locked door (shape 46)	;@1FE6
	jne CmdUnlock_NotHere	;@1FE8
	lea si, MsgWhoseKey	; "Whose key? "	;@1FEA
	call PrintMsg	;@1FEE
	mov si, bx	; SI = the door's cell	;@1FF1
	call AskPlayer	;@1FF3
	je CmdUnlock_Done	;@1FF6
	mov al, byte ptr [bx+26h]	; keys	;@1FF8
	sub al, 1	;@1FFB
	das	;@1FFD
	jb CmdUnlock_None	;@1FFE
	mov byte ptr [bx+26h], al	;@2000
	mov al, byte ptr TileHere	; TileHere = TileHere: the floor under the party	;@2003
	shl al, 1	;@2006
	shl al, 1	;@2008
	mov byte ptr [si], al	;@200A
	call BuildView	;@200C
CmdUnlock_Done:	jmp MainLoop	;@200F
CmdUnlock_NotHere:	jmp MsgNotHere	;@2012
CmdUnlock_None:	jmp MsgNoneLeft	;@2015
;------------------------------------------------------------------------------
; CmdVolume: V, Alt-S, Alt-V: sound on or off ("On!", "Off!").
;------------------------------------------------------------------------------
CmdVolume:	call PrintMsg	;@2018
	xor byte ptr SoundOn, 0FFh	;@201B
	lea si, MsgOff	; "Off!"	;@2020
	cmp byte ptr SoundOn, 0	;@2024
	je CmdVolume_Print	;@2029
	lea si, MsgOn	; "On!"	;@202B
CmdVolume_Print:	call PrintMsg	;@202F
	jmp MainLoop	;@2032
;------------------------------------------------------------------------------
; CmdXit: X-it the horse or frigate, on water or grass only: the craft stays
; on the map and the party is on foot; prints "Craft". On foot: "What?"; elsewhere "Not here!".
;------------------------------------------------------------------------------
CmdXit:	call PrintMsg	;@2035
	cmp byte ptr PartyTile, 3Fh	;@2038
	je CmdXit_What	;@203D
	mov bx, word ptr PlayerXY	;@203F
	call MapCellAddr	;@2043
	cmp al, 4	; water (0) or grass (4) only	;@2046
	ja CmdXit_NotHere	;@2048
	mov al, byte ptr PartyTile	; the craft's tile into the map	;@204A
	shl al, 1	;@204D
	shl al, 1	;@204F
	mov byte ptr [bx], al	;@2051
	mov byte ptr PartyTile, 3Fh	; on foot	;@2053
	lea si, MsgCraft	; "Craft"	;@2058
	call PrintMsg	;@205C
	jmp MainLoop	;@205F
CmdXit_What:	jmp MsgWhat	;@2062
CmdXit_NotHere:	jmp MsgNotHere	;@2065
;------------------------------------------------------------------------------
; CmdZtats: ask the player and show his Ztats (ShowZtats), DH = '1'-'4',
; DI = the record.
;------------------------------------------------------------------------------
CmdZtats:	call PrintMsg	;@2068
	call AskPlayer	;@206B
	je CmdZtats_Done	;@206E
	mov dh, al	;@2070
	mov di, bx	;@2072
	add dh, 30h	; the player's digit	;@2074
	call ShowZtats	;@2077
CmdZtats_Done:	jmp MainLoop	;@207A
CODE ENDS
END
